package com.weaponsregistration.reservation.model;import com.weaponsregistration.core.model.*;import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity@Table(name="erp_inventory_reservation")public class InventoryReservation extends CoreEntity{@ManyToOne(optional=false)@JoinColumn(name="organization_id",nullable=false)public Organization organization;@ManyToOne@JoinColumn(name="unit_id")public OrganizationalUnit unit;@ManyToOne(optional=false)@JoinColumn(name="status_type_id",nullable=false)public ReservationStatusType status;@Column(nullable=false)public String organizationName;@Column public String unitName;@Column(nullable=false,length=255)public String purpose;@Column(nullable=false)public LocalDateTime startsAt;@Column(nullable=false)public LocalDateTime endsAt;@Column(nullable=false)public LocalDateTime createdOn;@Column public LocalDateTime releasedAt;@Column public Long operatorId;@Column public String operatorLogin;@Column(nullable=false,unique=true,length=36)public String requestId;@Column(nullable=false,length=64)public String requestFingerprint;}
